#!/usr/bin/env python3
"""Build portable visible HUD/mask/animation authorization from current R3 + static profiles."""
from __future__ import annotations
import gzip,hashlib,json
from collections import Counter
from pathlib import Path
HERE=Path(__file__).resolve().parent
TRACE=HERE/'runtime/ordinary-rendering-hud-r3.trace.json.gz';TARGETS=HERE/'resource_pixi_rendering_hud_setter_targets.json';HUD=HERE/'resource_pixi_rendering_hud_asset_profiles.json';SKILL=HERE/'resource_pixi_rendering_skill_animation_profiles.json';NOTE=HERE/'resource_pixi_rendering_note_animation_profiles.json';R1=HERE/'resource_pixi_rendering_hud_runtime_profile.json';RESOURCE=HERE/'resource_pixi_rendering_resource_contract.json';PORTABLE=HERE/'resource_pixi_rendering_portable_contract.json';OUT=HERE/'resource_pixi_rendering_hud_visible_profile.json'
def load(p):return json.loads(p.read_text(encoding='utf-8'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest().upper()
def unique(events,sid,key):
 vals=[]
 for e in events:
  if e['setter_id']==sid:
   v=e['payload'].get(key)
   if v not in vals:vals.append(v)
 return vals
def main():
 trace=json.loads(gzip.decompress(TRACE.read_bytes()));events=trace['events'];hud=load(HUD);skill=load(SKILL);note=load(NOTE);r1=load(R1)
 counts=Counter(e['setter_id'] for e in events);assert len(events)==19888 and trace['summary']['relative_frame_count']==631
 sprites=[v for v in unique(events,'RPHU-002','technical_value') if v is not None];digits=sorted(v for v in sprites if v.startswith('icon_number_big_'));assert digits==[f'icon_number_big_{i}' for i in range(10)]
 plays=[e['payload'] for e in events if e['setter_id']=='RPHU-020'];names=sorted({p['technical_value'] for p in plays});assert names==['GameJudge','NoteLaneEffectAnimationDisabled','combo_number'];assert all(p['layer']==0 and p['normalized_time_f32_bits']=='00000000' for p in plays)
 doc={'schema_version':1,'status':'confirmed-current-ordinary-visible-hud-mask-animation-portable-profile','sample':trace['sample'],'source':{'trace_path':'runtime/ordinary-rendering-hud-r3.trace.json.gz','trace_bytes':TRACE.stat().st_size,'trace_sha256':sha(TRACE),'setter_targets_sha256':sha(TARGETS),'hud_asset_profiles_sha256':sha(HUD),'skill_animation_profiles_sha256':sha(SKILL),'note_animation_profiles_sha256':sha(NOTE),'hud_runtime_profile_sha256':sha(R1),'resource_contract_sha256':sha(RESOURCE),'portable_contract_sha256':sha(PORTABLE)},'coverage':{'events':len(events),'relative_frames':trace['summary']['relative_frame_count'],'setter_counts':dict(sorted(counts.items()))},'bitmap_hud':{'combo':{'digit_keys':digits,'widget_width':82,'widget_height':116,'depth':5,'play_state':'combo_number','play_count':sum(1 for p in plays if p['technical_value']=='combo_number'),'restart_normalized_time_f32_bits':'00000000'},'score':{'meter_key':'score_meter_blue','fill_f32_bits':unique(events,'RPHU-017','value_f32_bits')},'life':{'fill_f32_bits':unique(events,'RPHU-017','value_f32_bits'),'color_f32_bits':unique(events,'RPHU-004','color_f32_bits')},'skill_display':{'sprite_keys':sorted(v for v in sprites if v.startswith('icon_skill_score_up_')),'widget_sizes':[[86,20]],'alpha_f32_bits':unique(events,'RPHU-005','value_f32_bits')}},'field_mask':{'setup_owner':'RPH-030','sudden_owner':'RPH-031','game_object_active_observed':True,'local_scale_f32_bits':unique(events,'RPHU-016','value_f32_bits'),'serialized_mask_interaction_source':'resource_pixi_rendering_resource_contract.json + resource_pixi_rendering_portable_contract.json','runtime_mask_setter_observed':False,'portable_boundary':'serialized mask hierarchy plus observed setup/sudden transform; no Unity shader/raster parity'},'animations':{'combo_number':{'duration_seconds':hud['profiles']['combo_animation']['clips']['combo_number']['stop_time'],'runtime_restart_count':sum(1 for p in plays if p['technical_value']=='combo_number'),'loop':False,'portable_sampling':'sample frozen polynomial curves from command-local elapsed time; restart at zero; pause when engine step is frozen'},'game_judge':{'runtime_restart_count':sum(1 for p in plays if p['technical_value']=='GameJudge'),'restart_at_zero':True},'life_heal':{'duration_seconds':skill['clips']['life_heal']['stop_time'],'loop':False,'semantic_restart_before_life_update':r1['authorization']['life_heal_restart_before_life_update'],'portable_sampling':'sample frozen current curve from command-local elapsed time'},'score_skill':{'runtime_sprite_and_alpha_observed':True,'loop_duration_seconds':skill['clips']['score_up']['stop_time']},'flick_icon':{'duration_seconds':note['clips']['flick']['stop_time'],'loop':True,'runtime_assignment_observed':False}},'authorization':{'bitmap_combo_score_life':True,'bitmap_skill_score_up':True,'ordinary_field_sudden_mask':True,'combo_animation_sampling':True,'game_judge_animation_restart':True,'life_heal_animation_sampling':True,'score_skill_visible_overlay':True,'damage_guard_animation':False,'never_die_animation':False,'judge_skill_animation':False,'flick_icon_animation':False,'multiple_directional_visual':False},'limits':['portable-equivalent command-clock sampling excludes Unity PlayerLoop subframe and GPU raster parity','unobserved Damage Guard, Never Die, Judge Skill, Flick icon and Multiple routes remain fail-closed','technical UILabel values rejected by privacy filter remain sourced from engine semantic state, not from trace strings'],'unknown_fields':[]}
 OUT.write_text(json.dumps(doc,ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n');print('built visible HUD profile',len(events),'events')
if __name__=='__main__':main()
